function placesDirectory(graph){
 const nodes=new Map((graph?.topics||[]).map(t=>[t.id,t]));
 return `<div class="explore-places">${learningPlaces.map(p=>`<article><span class="explore-mark" aria-hidden="true">${p.mark}</span><div><h2>${p.title}</h2><p>${p.body}</p><a class="primary" href="${p.href}">Explore this place</a>${p.topics.length?`<details><summary>Grown-ups: ideas practiced here</summary>${p.topics.map(t=>`<p><a href="#map/${t.id}">${esc(nodes.get(t.id)?.name||'Learning connection')}</a>: ${esc(t.scope)}</p>`).join('')}</details>`:''}</div></article>`).join('')}</div><details class="panel"><summary>Grown-ups: how these places connect</summary><p>The invitations are original story connections, not prerequisite rules. Marble’s learning map separately shows its actual foundation and helpful links. A matching topic can describe only part of an activity; a context-only node has no activity attached. Visiting a place does not demonstrate understanding.</p><p>Help, pauses, and different starting places are welcome. Saved work follows each activity’s own resume rules; temporary Ribbon Recut and Body Movement pictures start again when you return.</p><a href="#map">Explore the learning map</a></details>`;
}
export function learningExplore(graph,slug){
 const q=exploreQuestions.find(x=>x.id===slug);
 if(q)return `<div class="explore-doorway explore-question"><header class="page-heading explore-heading"><a class="back" href="#explore">← All four questions</a><h1 id="explore-title" tabindex="-1">${esc(q.title)}</h1><p>${esc(q.story)}</p></header><p class="explore-choice-note">Start anywhere.</p><nav class="explore-destinations" aria-label="Places for this question">${q.links.map(([mark,href,title,reason])=>`<a href="${href}"><span class="explore-question-mark" aria-hidden="true">${mark}</span><span><strong>${esc(title)}</strong><small>${esc(reason)}</small></span><span class="explore-arrow" aria-hidden="true">↗</span></a>`).join('')}</nav><aside class="explore-contrast"><h2>Three ways to wonder</h2><p>${esc(q.contrast)}</p></aside><p class="explore-return"><a href="#explore">Choose another question</a> whenever you like. These places are all open.</p></div>`;
 return `<div class="explore-doorway"><header class="page-heading explore-heading"><a class="back" href="#home">← Back to the garden</a><h1 id="explore-title" tabindex="-1">Follow a curiosity.</h1><p>A puddle, a picnic, a message, a small neighbor. Choose any question that catches your eye.</p></header>${slug!==undefined?'<p class="explore-unknown" role="status">Choose a question from these four open paths.</p>':''}<nav class="explore-questions" aria-label="Four open questions">${exploreQuestions.map(q=>`<a href="#explore/${q.id}"><span class="explore-question-mark" aria-hidden="true">${q.mark}</span><span><strong>${esc(q.title)}</strong><small>${esc(q.teaser)}</small></span><span class="explore-arrow" aria-hidden="true">↗</span></a>`).join('')}</nav><details class="explore-all-places"><summary>All places</summary><p>Every place stays open. Choose a familiar place, or find another.</p>${placesDirectory(graph)}</details></div>`;
}
